insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('sam-3412-asks-relayed-2026-11-16','fact','Sam''s CPL Pathways and College Data Collection asks after the Credential Engine demo, relayed by COBIx (#3412)','Sam, 2026-11-16, 2:05 to 2:26 PM PT, relayed by COBIx on #3412: an SLOs chip that expands a course card in place; drill from a subject to a course''s SLO text and reach PLOs in College Data Collection; one composite Request Adopt chip with a multi-select panel, region-first college naming, on CPL Pathways and the CPL Opportunity page; rename View CPL Visual to Create My College CPL Plan.',array['cpl-pathways','commons','sam'],'proposed','COBIx relay on #3412 of Sam''s asks, 2026-11-16',null,null,'S669',date '2026-11-16'),
('d-3412-built-s669','decision','#3412 built: in-card SLOs chip, the Commons drill to SLO and PLO text, one composite Adopt chip','S669: #3415 (merged) adds a chip beside the outcomes word that opens the text on the card, sharing fillOutcomes with the panel. #3422 drills subject to course to SLO text and adds a PLO section reusing the committed list. #3424 adds adopt_panel.js (window.CPL_ADOPT_PANEL), one chip and multi-select panel on Pathways and the Opportunity page, and lifts adopt[:4] in the display build.',array['cpl-pathways','commons','decision'],'proposed','S669; #3415, #3422, #3424',null,null,'S669',date '2026-11-16'),
('d-align-lexical-held-off-s669','decision','No chip from the lexical alignment of unreviewed credentials','S669, #3410, #3413, #3416: scoring 191 unreviewed credentials'' issuer skill areas against every harvested course gave 151 standouts at all 19 colleges on every word, and 24 on distinctive words with a course-title gate, about a quarter still wrong (CSSLP to aviation maintenance). chips_shown stays false; a semantic scorer comes first, re-measured before any chip.',array['credential-catalog','library','decision'],'proposed','S669; the library lane',null,null,'S669',date '2026-11-16'),
('p-lexical-cover-rule-overmatches-s669','pitfall','A word-overlap cover rule over every course matches everything','S669: the settled analysis''s 0.20 cosine rule works against one college''s articulated courses, but scored against all 14,843 courses it lets common words (planning, management, systems) cover short skill areas, so nearly every credential matched every college. Restrict to distinctive words and gate on the course title; even then a lexical score is not a chip.',array['credential-catalog','pitfall'],'proposed','S669; #3410, #3413',null,null,'S669',date '2026-11-16')
